mapper.select:
/* statsInqyDao1020 : 입·퇴사 현황 목록 조회 */ SELECT CASE WHEN G_ORG = 1 THEN '전체 합계' ELSE ORG_NM END AS ORG_NM , CASE WHEN G_YM = 1 THEN '연간 소계' ELSE YEAR_MM END AS YEAR_MM , HIRE_TOTAL , LEAV_TOTAL , G_ORG , G_YM FROM ( SELECT ORG_CD , MAX(ORG_NM) AS ORG_NM , YEAR_MM , SUM(HIRE_SUM) AS HIRE_TOTAL , SUM(LEAV_SUM) AS LEAV_TOTAL , GROUPING(ORG_CD) AS G_ORG , GROUPING(YEAR_MM) AS G_YM FROM ( SELECT E.ORG_CD , O.ORG_NM , TO_CHAR(E.HIRE_DT, 'YYYYMM') AS YEAR_MM , COUNT(E.EMP_IDX) AS HIRE_SUM , 0 AS LEAV_SUM FROM EMP_INFO E LEFT OUTER JOIN ORG O ON E.ORG_CD = O.ORG_CD WHERE E.HIRE_DT >= TO_DATE(NVL(#{srchYearCd, jdbcType=VARCHAR}, TO_CHAR(SYSDATE, 'YYYY')) || '0101', 'YYYYMMDD') AND E.HIRE_DT < ADD_MONTHS( TO_DATE(NVL(#{srchYearCd, jdbcType=VARCHAR}, TO_CHAR(SYSDATE, 'YYYY')) || '0101', 'YYYYMMDD'), 12) GROUP BY E.ORG_CD, O.ORG_NM, TO_CHAR(E.HIRE_DT, 'YYYYMM') UNION ALL SELECT E.ORG_CD , O.ORG_NM , TO_CHAR(E.LEAV_DT, 'YYYYMM') AS YEAR_MM , 0 AS HIRE_SUM , COUNT(E.EMP_IDX) AS LEAV_SUM FROM EMP_INFO E LEFT OUTER JOIN ORG O ON E.ORG_CD = O.ORG_CD WHERE E.LEAV_DT >= TO_DATE(NVL(#{srchYearCd, jdbcType=VARCHAR}, TO_CHAR(SYSDATE, 'YYYY')) || '0101', 'YYYYMMDD') AND E.LEAV_DT < ADD_MONTHS(TO_DATE(NVL(#{srchYearCd, jdbcType=VARCHAR}, TO_CHAR(SYSDATE, 'YYYY')) || '0101', 'YYYYMMDD'), 12) GROUP BY E.ORG_CD, O.ORG_NM, TO_CHAR(E.LEAV_DT, 'YYYYMM') ) GROUP BY GROUPING SETS ((ORG_CD, YEAR_MM), (ORG_CD), (YEAR_MM), ()) ) WHERE 1 = 1
AND REGEXP_REPLACE(LOWER(ORG_NM), '[^0-9가-힣A-Za-z]', '') LIKE '%' || REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}), '[^0-9가-힣A-Za-z]', '') || '%'
ORDER BY G_ORG, ORG_CD, G_YM, YEAR_MM
